import{_ as o,o as r,c as t,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Troubleshooting: Video Export","description":"Fix local and cloud rendering issues.","frontmatter":{"title":"Troubleshooting: Video Export","description":"Fix local and cloud rendering issues."},"headers":[],"relativePath":"support/troubleshooting_export.md","filePath":"support/troubleshooting_export.md"}'),n={name:"support/troubleshooting_export.md"};function a(i,e,l,d,u,c){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting-video-export" tabindex="-1">Troubleshooting: Video Export <a class="header-anchor" href="#troubleshooting-video-export" aria-label="Permalink to &quot;Troubleshooting: Video Export&quot;">​</a></h1><h2 id="_1-local-browser-render-freezes" tabindex="-1">1. Local Browser Render Freezes <a class="header-anchor" href="#_1-local-browser-render-freezes" aria-label="Permalink to &quot;1. Local Browser Render Freezes&quot;">​</a></h2><p><strong>Symptom:</strong> You select &quot;Local Browser Render&quot;, but the progress bar gets stuck halfway. <strong>Cause:</strong> Browsers throttle or pause background tabs to save memory. <strong>Solution:</strong></p><ul><li>Keep the Sanjeev AI tab active and visible during the entire render process.</li><li>Do not minimize the window or switch to another heavy website (like YouTube or a heavy web app) while rendering.</li></ul><h2 id="_2-screen-sleeps-during-export" tabindex="-1">2. Screen Sleeps During Export <a class="header-anchor" href="#_2-screen-sleeps-during-export" aria-label="Permalink to &quot;2. Screen Sleeps During Export&quot;">​</a></h2><p><strong>Symptom:</strong> Your computer screen turns off during a local export, causing the render to fail. <strong>Cause:</strong> While Sanjeev AI requests a &quot;Screen Wake Lock&quot; to prevent your device from sleeping, some browsers (like Firefox) or extreme battery-saver modes block this API. <strong>Solution:</strong> Use Google Chrome or Microsoft Edge, plug your device into a power source, and temporarily disable aggressive screen-sleep settings in your OS.</p><h2 id="_3-cloud-render-job-stuck" tabindex="-1">3. Cloud Render Job Stuck <a class="header-anchor" href="#_3-cloud-render-job-stuck" aria-label="Permalink to &quot;3. Cloud Render Job Stuck&quot;">​</a></h2><p><strong>Symptom:</strong> You initiate a Cloud Render (FFmpeg), but the status remains &quot;Rendering&quot; for over 15 minutes. <strong>Cause:</strong> The backend server worker may have crashed during the stitching process (often due to a corrupt visual asset). <strong>Solution:</strong></p><ul><li>Reload the page.</li><li>If the status is still stuck, the job is dead. You can safely initiate a new Cloud Render.</li></ul><h2 id="_4-video-download-fails-on-mobile" tabindex="-1">4. Video Download Fails on Mobile <a class="header-anchor" href="#_4-video-download-fails-on-mobile" aria-label="Permalink to &quot;4. Video Download Fails on Mobile&quot;">​</a></h2><p><strong>Symptom:</strong> The final MP4 finishes rendering, but the &quot;Download&quot; button does nothing on iOS Safari. <strong>Cause:</strong> iOS handles direct MP4 blobs differently. <strong>Solution:</strong> Long-press the generated video and select &quot;Save to Photos&quot;, or use a desktop browser for video exporting.</p>',11)])])}const g=o(n,[["render",a]]);export{h as __pageData,g as default};
